import { createApp } from "../src/app.ts";
import { ManualClock } from "../src/clock.ts";
import { sequentialIds } from "../src/ids.ts";
import { MemoryStore } from "../src/store/memory.ts";

describe("authz.permission-evaluation freshness", () => {
  it("denies a revoked collaborator on their very next request", async () => {
    const deps = {
      store: new MemoryStore(),
      clock: new ManualClock(0),
      ids: sequentialIds(),
    };
    const app = createApp(deps);

    async function api(method: string, path: string, opts: { token?: string; body?: object } = {}) {
      const headers: Record<string, string> = {};
      if (opts.token) headers.authorization = `Bearer ${opts.token}`;
      if (opts.body !== undefined) headers["content-type"] = "application/json";
      return app.request(path, {
        method,
        headers,
        body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined,
      });
    }

    function observe(actor: string, method: string, path: string, status: number, expected: number) {
      console.log(`[probe] ${actor} ${method} ${path} -> ${status} (expected ${expected})`);
    }

    let res = await api("POST", "/users", { body: { username: "owner", password: "password1234", name: "Owner" } });
    observe("owner", "POST", "/users", res.status, 201);
    expect(res.status).toBe(201);

    res = await api("POST", "/users", { body: { username: "collab", password: "password1234", name: "Collab" } });
    observe("collab", "POST", "/users", res.status, 201);
    expect(res.status).toBe(201);

    res = await api("POST", "/sessions", { body: { username: "owner", password: "password1234" } });
    observe("owner", "POST", "/sessions", res.status, 201);
    expect(res.status).toBe(201);
    const ownerToken = (await res.json()).token;

    res = await api("POST", "/sessions", { body: { username: "collab", password: "password1234" } });
    observe("collab", "POST", "/sessions", res.status, 201);
    expect(res.status).toBe(201);
    const collabToken = (await res.json()).token;

    res = await api("POST", "/repos", { token: ownerToken, body: { name: "repo", visibility: "private" } });
    observe("owner", "POST", "/repos", res.status, 201);
    expect(res.status).toBe(201);

    res = await api("PUT", "/repos/owner/repo/collaborators/collab", { token: ownerToken, body: { role: "write" } });
    observe("owner", "PUT", "/repos/owner/repo/collaborators/collab", res.status, 201);
    expect(res.status).toBe(201);

    const refPath = "/repos/owner/repo/refs/heads/main";
    res = await api("PUT", refPath, { token: collabToken, body: { sha: "0".repeat(40) } });
    observe("collab", "PUT", refPath, res.status, 201);
    expect(res.status).toBe(201);

    const revokePath = "/repos/owner/repo/collaborators/collab";
    res = await api("DELETE", revokePath, { token: ownerToken });
    observe("owner", "DELETE", revokePath, res.status, 204);

    if (res.status === 404) {
      const contentType = res.headers.get("content-type") ?? "";
      const body = await res.text();
      if (contentType.includes("text/plain") && body === "404 Not Found") {
        throw new Error("probe not applicable: revoke route is absent");
      }
    }

    expect(res.status).toBe(204);

    res = await api("PUT", refPath, { token: collabToken, body: { sha: "1".repeat(40) } });
    observe("collab", "PUT", refPath, res.status, 404);
    expect(res.status).toBe(404);
  });
});"}, "rationale": "The probe exercises A's new DELETE revoke route to remove a collaborator who has already used their write access, then asserts that the collaborator's very next request is denied. With per-request freshness (A), the revocation is visible immediately and the private repository returns 404; with B's per-session role cache, the collaborator's cached "write" role lets the same request succeed, causing the probe to fail. If the revoke route is absent (base or B alone), the DELETE hits Hono's default text/plain 404, so the probe throws the required n/a error. The test also fails if A's revoke does nothing, because the collaborator would still be allowed."}

